function applyExtensionTranslations(root = document.querySelector('#rm_extensions_block')) {
  if (!root) return;
  const bilingual = localStorage.getItem('hsbc-tavern.chinese-subtitles') === 'true';
  root.querySelectorAll('#extensions_settings .extension_container :is(h2,h3,h4,.inline-drawer-toggle,.inline-drawer-header)').forEach(title => {
    const old = title.querySelector(':scope > .hsbc-extension-zh');
    if (!bilingual) { old?.remove(); return; }
    const source = [...title.childNodes].filter(node => node.nodeType === Node.TEXT_NODE).map(node => node.textContent).join(' ').replace(/\s+/g, ' ').trim() || title.getAttribute('title') || title.textContent.replace(/\s+/g, ' ').trim();
    const subtitle = old || document.createElement('small'); subtitle.className = 'hsbc-extension-zh'; const translated = EXTENSION_ZH.get(source) || '\u6269\u5c55\u8bbe\u7f6e'; if (subtitle.textContent !== translated) subtitle.textContent = translated;
    if (!old) title.append(subtitle);
  });
}

